"""Thin paired lease and configured-root wiring tests; no solver invocation."""
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest

ROOT = Path(__file__).resolve().parents[3]
PWSH = shutil.which("pwsh")

@unittest.skipUnless(PWSH, "PowerShell 7 required")
class PairedInheritedLeaseTests(unittest.TestCase):
    def test_actual_inherited_exit_and_noninherited_failure_propagation(self):
        code = 'param($Repo,$Draft,$Python)\n$ErrorActionPreference=\'Stop\';Set-StrictMode -Version Latest\n$hostContext=@{workspace=$Repo;python_executable=$Python;host_state_path=(Join-Path $Repo \'fixture.sqlite3\');policy_path=(Join-Path $Repo \'src/msplatform/execution/resources/host_resource_policy.json\')}\n. (Join-Path $Repo \'src/msplatform/execution/resources/host_execution_lease.ps1\') -HostContext $hostContext\nfunction Import-Function($Path,$Name){\n $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors)\n if($errors.Count){throw ($errors|Out-String)}\n $node=$ast.Find({param($n)$n-is[Management.Automation.Language.FunctionDefinitionAst]-and$n.Name-eq$Name},$true)\n if(-not$node){throw (\'Missing function \'+$Name)}\n return [scriptblock]::Create($node.Extent.Text)\n}\n$workflow=Join-Path $Draft \'src/msplatform/workflows/resources/run_artifact_workflow.ps1\'\n. (Import-Function $workflow \'Assert-WorkflowFields\')\n. (Import-Function $workflow \'Assert-WorkflowWriterCompletion\')\n. (Import-Function $workflow \'Add-RunArtifactResourceRelease\')\nforeach($owner in @(\'paired_accelerator_pulse\')){\n . (Import-Function (Join-Path $Draft "src/msplatform/workflows/resources/$owner.ps1") \'Close-PairedHostStage\')\n $lease=@{inherited=$true;token=\'TEST_ONLY_PARENT\';environment_set=$false}\n $writerUnknown=$false;$hostReleaseUnknown=$false\n $nativeOperations=[Collections.Generic.List[object]]::new();$resourceReleases=[Collections.Generic.List[object]]::new()\n $nativeOperations.Add(@{operation_id=\'inert\';resource_release_id=\'TEST_ONLY_PARENT\';observation=@{exit_confirmed=$true;returncode=0;process_id=$PID;process_started_at_utc_ticks=(Get-Process -Id $PID).StartTime.ToUniversalTime().Ticks}})\n function Invoke-HostResourceTransaction {throw \'Inherited Exit must never release its parent\'}\n Close-PairedHostStage\n if($null-ne$lease-or$writerUnknown-or$hostReleaseUnknown-or$resourceReleases.Count-ne1-or$null-ne$resourceReleases[0].completion_receipt.host_release.result){throw \'Actual inherited null receipt was not preserved\'}\n $lease=@{inherited=$true;token=\'TEST_ONLY_PARENT\';environment_set=$false}\n $nativeOperations.Add(@{operation_id=\'second-inert\';resource_release_id=\'TEST_ONLY_PARENT\';observation=@{exit_confirmed=$true;returncode=0;process_id=$PID;process_started_at_utc_ticks=(Get-Process -Id $PID).StartTime.ToUniversalTime().Ticks}})\n Close-PairedHostStage\n Add-RunArtifactResourceRelease -ResourceReleases $resourceReleases -ReleaseId \'TEST_ONLY_PARENT\' -Receipt @{host_release=@{inherited=$true;token=\'TEST_ONLY_PARENT\';result=$null;error=$null};operations=@()}\n if($resourceReleases.Count-ne1-or$nativeOperations.Count-ne2){throw \'Repeated inherited stage lost operations or duplicated parent release\'}\n $rejected=$false;try{Add-RunArtifactResourceRelease -ResourceReleases $resourceReleases -ReleaseId \'TEST_ONLY_PARENT\' -Receipt @{host_release=@{inherited=$true;token=\'OTHER\';result=$null;error=$null}}}catch{$rejected=$true}\n if(-not$rejected){throw \'Conflicting duplicate release hidden\'}\n $completion=@{operations=@($nativeOperations.ToArray());resource_releases=@($resourceReleases.ToArray())}\n Assert-WorkflowWriterCompletion $completion -PowerShellOwner\n $completion.resource_releases[0].completion_receipt.host_release.inherited=$false\n $rejected=$false;try{Assert-WorkflowWriterCompletion $completion -PowerShellOwner}catch{$rejected=$true}\n if(-not$rejected){throw \'Null noninherited release accepted\'}\n $completion.resource_releases[0].completion_receipt.host_release.inherited=$true\n $completion.resource_releases[0].completion_receipt.host_release.result=@{status=\'acquired\';token=\'TEST_ONLY_PARENT\'}\n $rejected=$false;try{Assert-WorkflowWriterCompletion $completion -PowerShellOwner}catch{$rejected=$true}\n if(-not$rejected){throw \'Invented inherited transaction accepted\'}\n foreach($failure in @(\'null\',\'throw\',\'wrong_token\')){\n  $lease=@{inherited=$false;token=\'TEST_ONLY_PARENT\';environment_set=$false;completed_work_processes=@();state_path=\'TEST_ONLY\';role=\'SIMION\';stage=\'flight\'}\n  $writerUnknown=$false;$hostReleaseUnknown=$false\n  function Invoke-HostResourceTransaction {param($StatePath,$Request);if($failure-eq\'throw\'){throw \'PRIMARY_RELEASE_FAILURE\'};if($failure-eq\'wrong_token\'){return @{status=\'released\';token=\'OTHER\'}};return $null}\n  $caught=$null;try{Close-PairedHostStage}catch{$caught=$_}\n  if($null-eq$caught-or-not$writerUnknown-or-not$hostReleaseUnknown-or$null-eq$lease){throw \'Unconfirmed real release did not preserve protection\'}\n  if($failure-eq\'throw\'-and$caught.Exception.Message-ne\'PRIMARY_RELEASE_FAILURE\'){throw \'Primary error masked\'}\n }\n}\n\'PAIRED_INHERITED_AND_RELEASE_FAILURES=PASS\'\n'
        with tempfile.TemporaryDirectory() as directory:
            script = Path(directory) / "check.ps1"
            script.write_text(code, encoding="utf-8", newline="\n")
            result = subprocess.run([PWSH, "-NoProfile", "-File", str(script), "-Repo", str(ROOT), "-Draft", str(ROOT), "-Python", sys.executable], cwd=ROOT,capture_output=True, text=True, encoding="utf-8", timeout=30)
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
